-- blocks-boutique-steenberg (owner)
UPDATE businesses SET description = 'Blocks Boutique is a barbershop at 144 Military Road in Steenberg, Cape Town, focused on men''s hair care and traditional grooming. The shop offers a relaxed, welcoming setting where local men and young men can drop in for a fresh cut and a neat finish, with the barbers taking care over the small details that make a cut look sharp.

Services cover contemporary men''s haircuts, clean head shaves and beard trims that tidy up the shape and lines of a beard. For a more traditional experience, the barbers also offer hot towel shaves, where warm towels soften the skin and hair before a close, smooth shave. Whether a customer wants a quick tidy-up between cuts or a full refresh before a special occasion, the team works to leave each client looking clean and well groomed. Being on Military Road makes the shop easy to reach for residents of Steenberg and the surrounding southern suburbs. Blocks Boutique is at 144 Military Road, Steenberg, Cape Town.', description_enriched_at = datetime('now') WHERE slug = 'blocks-boutique-steenberg' AND description = 'Blocks Boutique is a barbershop in Steenberg offering men''s haircuts, hot towel shaves, head shaves and beard trims.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
