-- mr-price-kids-cape-town-cbd (owner)
UPDATE businesses SET description = 'Mr Price Kids is a children''s clothing store inside the Golden Acre Shopping Centre at 9 Adderley Street in the Cape Town CBD. Part of the Mr Price group, the store focuses on affordable, on-trend clothing for babies, toddlers and young children, making it easy for parents to keep up with fast-growing kids without overspending.

The range covers colourful everyday outfits, comfortable sleepwear, durable shoes for school and play, and fun accessories that change with the seasons. Baby basics such as bodysuits and soft sets sit alongside fashion pieces for older children, so families can shop for several ages in one visit. New styles arrive regularly, which keeps the shelves fresh for parents who like to dress their children in current looks at budget-friendly prices. Being in Golden Acre, close to the Cape Town station and the city''s main taxi and bus routes, the store is a convenient stop for commuters and city workers shopping on the way home. Mr Price Kids is at Golden Acre Shopping Centre, 9 Adderley Street, Cape Town CBD.', description_enriched_at = datetime('now') WHERE slug = 'mr-price-kids-cape-town-cbd' AND description = 'Mr Price Kids is a branch of the Mr Price Kids children''s fashion chain, located in the Golden Acre Shopping Centre.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
